import{_ as a,o as s,c as o,a2 as i}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 48 话 File System Access API：网页直接读写本地文件","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.48-file-system-access.md","filePath":"comics/html/EP.48-file-system-access.md","lastUpdated":1792579602000}'),t={name:"comics/html/EP.48-file-system-access.md"};function c(l,e,r,d,h,n){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-48-话-file-system-access-api-网页直接读写本地文件" tabindex="-1">漫画 · 第 48 话 File System Access API：网页直接读写本地文件 <a class="header-anchor" href="#漫画-·-第-48-话-file-system-access-api-网页直接读写本地文件" aria-label="Permalink to &quot;漫画 · 第 48 话 File System Access API：网页直接读写本地文件&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/18-file-system-access">docs/html/18-file-system-access.md</a> ｜ 原画：<a href="./EP.48-file-system-access.svg">EP.48-file-system-access.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。网页版 Markdown 编辑器，用户吐槽「保存就是下载副本，不像 VS Code 直接写本地」。打开文件靠 <code>&lt;input type=&quot;file&quot;&gt;</code>，批量处理图片要先上传再下载，体验割裂。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 File System Access API 三件套——<code>showOpenFilePicker</code> 打开文件、<code>showSaveFilePicker</code> 保存文件、<code>showDirectoryPicker</code> 读写目录，让网页获得原生应用级的文件系统能力。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>网页长期被「文件操作」这道墙挡住：保存就是下载副本、打开就是 input 框、无法批量处理目录。File System Access API 打破这道墙——打开文件选择器返回文件句柄，保存直接写入本地磁盘，目录操作支持遍历和创建。配合 IndexedDB 持久化句柄，用户授权一次，后续直接读写。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>用户抱怨：保存 = 下载副本（不是覆盖原文件）、打开 = input type=file（无法记住上次路径）、无法直接读写本地、无法批量处理文件。竞品原生体验，用户流失。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三件套：<code>showOpenFilePicker</code> 打开文件返回 FileSystemFileHandle，<code>showSaveFilePicker</code> 保存文件返回句柄，<code>showDirectoryPicker</code> 打开目录返回 FileSystemDirectoryHandle。读写通过 <code>createWritable</code> 实现，权限通过 <code>queryPermission/requestPermission</code> 管理。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：文本编辑器（打开 .md 文件、Ctrl+S 直接保存）、图片批处理（读取目录树、批量压缩）、权限持久化（句柄存 IndexedDB、下次直接读写）、兼容性注意（Chrome 86+ 全绿、Safari 15.2+ 部分支持、Firefox 不支持）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>showOpenFilePicker</code> / <code>showSaveFilePicker</code> / <code>showDirectoryPicker</code> 三件套。</li><li>句柄可存 IndexedDB 持久化；权限是临时的，刷新后需重新请求。</li><li>Chrome 86+ / Safari 15.2+ 支持；Firefox 不支持——必须特性检测。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 File System Access API 返回的句柄要存入 IndexedDB，而不是直接存在内存中？</p><p><strong>答</strong>：句柄存内存会在页面刷新后丢失。存入 IndexedDB 后，下次打开页面可以直接读取句柄，调用 <code>queryPermission</code> 检查权限是否仍有效——用户无需重新选择文件或目录，实现「记住最近文件」功能。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>打开文件 + 保存文件 + 读写目录 + 权限管理：<a href="./../../examples/html/18-file-system-access/index-01-file-system-access.html">examples/html/18-file-system-access/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>霓虹墨 Neon Ink 漫画剧场至此完结——CSS3 × HTML5 从基础到进阶，48 话覆盖 20+ 核心主题。感谢像素酱、标签君、码叔的一路陪伴，深入阅读与动手实验永不停止。</p>',22)])])}const f=a(t,[["render",c]]);export{u as __pageData,f as default};
